mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search doctors by specialty, location, and insurance. Read verified reviews and book same-day appointments in minutes with MedBook." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: oklch(58% 0.22 258);
      --primary-strong: oklch(52% 0.24 258);
      --primary-soft: oklch(96% 0.03 258);
      --accent: oklch(72% 0.14 172);
      --accent-strong: oklch(64% 0.16 172);
      --surface: oklch(100% 0 0);
      --surface-alt: oklch(97% 0.01 250);
      --text: oklch(24% 0.02 255);
      --text-muted: oklch(48% 0.02 255);
      --border: oklch(90% 0.01 255);
      --shadow: 0 16px 40px color-mix(in oklab, var(--primary) 10%, transparent);
      --radius-lg: 20px;
      --radius-md: 14px;
      --radius-sm: 10px;
      --container: min(1120px, 92vw);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: var(--surface);
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: var(--container); margin-inline: auto; }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: color-mix(in oklab, white 90%, var(--primary-soft));
      border-bottom: 1px solid var(--border);
      backdrop-filter: blur(8px);
    }

    .header-row {
      min-height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      font-size: 1.4rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      color: var(--primary-strong);
      display: inline-flex;
      align-items: center;
      gap: .55rem;
    }

    .brand-mark {
      width: 30px;
      height: 30px;
      border-radius: 9px;
      background: linear-gradient(145deg, var(--primary), var(--accent));
      box-shadow: 0 8px 18px color-mix(in oklab, var(--primary) 38%, transparent);
      position: relative;
    }

    .brand-mark::before {
      content: '+';
      color: white;
      font-weight: 800;
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      font-size: 1rem;
    }

    .desktop-nav {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      font-weight: 500;
      color: var(--text-muted);
    }

    .desktop-nav a:hover { color: var(--primary-strong); }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .45rem;
      border: none;
      cursor: pointer;
      border-radius: 999px;
      font-weight: 700;
      transition: transform .2s ease, box-shadow .2s ease, background-color .2s ease;
    }

    .btn:focus-visible, .icon-btn:focus-visible, .field:focus-visible {
      outline: 3px solid color-mix(in oklab, var(--primary) 35%, white);
      outline-offset: 2px;
    }

    .btn:hover { transform: translateY(-1px); }
    .btn-primary {
      background: linear-gradient(140deg, var(--primary), var(--primary-strong));
      color: white;
      padding: .75rem 1.2rem;
      box-shadow: 0 12px 24px color-mix(in oklab, var(--primary) 28%, transparent);
    }
    .btn-accent {
      background: linear-gradient(140deg, var(--accent), var(--accent-strong));
      color: white;
      padding: 1rem 1.4rem;
      font-size: 1rem;
    }

    .icon-btn {
      display: none;
      border: 1px solid var(--border);
      background: white;
      width: 44px;
      height: 44px;
      border-radius: 12px;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }

    .hero {
      padding: 4.5rem 0 2.25rem;
      background:
        radial-gradient(circle at 0% 0%, color-mix(in oklab, var(--primary) 14%, white), transparent 42%),
        radial-gradient(circle at 100% 0%, color-mix(in oklab, var(--accent) 14%, white), transparent 40%),
        white;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      gap: 2rem;
      align-items: center;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.5rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .hero p {
      margin: 1rem 0 0;
      color: var(--text-muted);
      font-size: 1.08rem;
      max-width: 62ch;
    }

    .trust-row {
      margin-top: 1.3rem;
      display: flex;
      flex-wrap: wrap;
      gap: .65rem;
    }

    .pill {
      padding: .52rem .8rem;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: white;
      color: var(--text-muted);
      font-size: .92rem;
      font-weight: 600;
    }

    .hero-illustration {
      background: linear-gradient(160deg, color-mix(in oklab, var(--primary) 14%, white), white);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: 1.1rem;
    }

    .doc-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: .9rem;
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: .8rem;
      margin-bottom: .75rem;
    }

    .avatar {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: color-mix(in oklab, var(--primary) 14%, white);
      display: grid;
      place-items: center;
      color: var(--primary-strong);
      font-weight: 700;
      font-size: .9rem;
    }

    .doc-name { margin: 0; font-weight: 700; font-size: .95rem; }
    .doc-meta { margin: 0; color: var(--text-muted); font-size: .85rem; }
    .badge {
      padding: .35rem .6rem;
      border-radius: 999px;
      background: color-mix(in oklab, var(--accent) 18%, white);
      color: oklch(40% 0.1 172);
      font-size: .78rem;
      font-weight: 700;
    }

    .search-section { margin-top: -1.2rem; padding-bottom: 3.2rem; }

    .search-shell {
      border: 1px solid var(--border);
      border-radius: 22px;
      background: white;
      box-shadow: 0 24px 45px color-mix(in oklab, var(--primary) 13%, transparent);
      padding: 1rem;
    }

    .search-title {
      margin: 0 0 .8rem;
      font-size: 1.03rem;
      font-weight: 700;
      color: var(--text-muted);
    }

    .search-form {
      display: grid;
      grid-template-columns: 1.2fr .9fr auto;
      gap: .75rem;
      position: relative;
    }

    .field-wrap { position: relative; }

    .field {
      width: 100%;
      border: 1px solid var(--border);
      background: oklch(99% 0 0);
      color: var(--text);
      border-radius: 14px;
      min-height: 56px;
      padding: 0 .95rem;
      font-size: 1rem;
      font-family: inherit;
    }

    .suggestions {
      position: absolute;
      top: calc(100% + .4rem);
      left: 0;
      right: 0;
      background: white;
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: 0 14px 30px rgba(6, 26, 49, .13);
      overflow: hidden;
      z-index: 20;
      display: none;
      max-height: 300px;
      overflow-y: auto;
    }

    .suggestion {
      width: 100%;
      border: none;
      background: white;
      text-align: left;
      padding: .78rem .85rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: .55rem;
      font-size: .95rem;
    }

    .suggestion:hover, .suggestion.active {
      background: color-mix(in oklab, var(--primary) 9%, white);
    }

    .section { padding: 3.8rem 0; }
    .section-alt { background: var(--surface-alt); }
    .section h2 {
      margin: 0 0 .8rem;
      font-size: clamp(1.5rem, 2.6vw, 2.3rem);
      line-height: 1.2;
      letter-spacing: -0.02em;
    }
    .section .lead {
      margin: 0 0 1.8rem;
      color: var(--text-muted);
      max-width: 66ch;
      font-size: 1.02rem;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: .9rem;
      margin-top: .5rem;
    }

    .stat {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1rem;
    }

    .stat strong {
      display: block;
      font-size: clamp(1.2rem, 2vw, 1.6rem);
      color: var(--primary-strong);
      line-height: 1.25;
    }

    .stat span { color: var(--text-muted); font-size: .92rem; }

    .specialty-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: .9rem;
    }

    .specialty-card {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1rem;
      display: flex;
      align-items: center;
      gap: .75rem;
      font-weight: 700;
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .specialty-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow);
      border-color: color-mix(in oklab, var(--primary) 40%, white);
    }

    .icon {
      width: 38px;
      height: 38px;
      border-radius: 11px;
      display: grid;
      place-items: center;
      color: var(--primary-strong);
      background: color-mix(in oklab, var(--primary) 12%, white);
      flex-shrink: 0;
    }

    .steps { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .95rem; }
    .step {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1rem;
    }

    .step-index {
      width: 30px;
      height: 30px;
      border-radius: 9px;
      display: grid;
      place-items: center;
      font-size: .85rem;
      color: white;
      background: linear-gradient(145deg, var(--primary), var(--accent));
      margin-bottom: .7rem;
      font-weight: 700;
    }

    .testimonials { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .9rem; }
    .quote {
      background: white;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      padding: 1rem;
    }

    .quote p { margin: 0 0 .8rem; color: var(--text-muted); }
    .quote strong { font-size: .92rem; }

    .app-promo {
      border: 1px solid var(--border);
      background: linear-gradient(145deg, color-mix(in oklab, var(--primary) 8%, white), color-mix(in oklab, var(--accent) 10%, white));
      border-radius: var(--radius-lg);
      padding: 1.5rem;
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 1rem;
      align-items: center;
    }

    .store-row { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 1rem; }

    .store-btn {
      border: 1px solid var(--border);
      background: white;
      padding: .7rem 1rem;
      border-radius: 12px;
      font-weight: 700;
      font-size: .9rem;
      display: inline-flex;
      align-items: center;
      gap: .45rem;
    }

    .app-features { margin: 0; padding: 0; list-style: none; }
    .app-features li {
      background: white;
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: .65rem .8rem;
      margin-bottom: .55rem;
      font-weight: 600;
      font-size: .92rem;
    }

    .footer {
      padding: 3rem 0 1.4rem;
      background: oklch(20% 0.02 255);
      color: oklch(94% 0.01 255);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .footer h3 { margin: 0 0 .65rem; font-size: 1rem; }
    .footer a { display: block; color: oklch(86% 0.01 255); margin-bottom: .45rem; font-size: .93rem; }
    .footer a:hover { color: white; }

    .copyright {
      margin-top: 1.6rem;
      padding-top: 1rem;
      border-top: 1px solid color-mix(in oklab, white 20%, transparent);
      color: oklch(82% 0.01 255);
      font-size: .88rem;
    }

    .mobile-drawer {
      position: fixed;
      inset: 0 0 0 auto;
      width: min(82vw, 320px);
      background: white;
      border-left: 1px solid var(--border);
      box-shadow: -20px 0 40px rgba(0,0,0,.1);
      transform: translateX(100%);
      transition: transform .28s ease;
      z-index: 60;
      padding: 1.1rem;
    }
    .mobile-drawer.open { transform: translateX(0); }
    .drawer-overlay {
      position: fixed;
      inset: 0;
      background: rgba(8, 17, 28, .4);
      opacity: 0;
      pointer-events: none;
      transition: opacity .28s ease;
      z-index: 50;
    }
    .drawer-overlay.open { opacity: 1; pointer-events: auto; }

    .drawer-links a {
      display: block;
      padding: .9rem .2rem;
      border-bottom: 1px solid var(--border);
      font-weight: 600;
    }

    @media (max-width: 980px) {
      .hero-grid,
      .app-promo { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .specialty-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .steps,
      .testimonials,
      .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    }

    @media (max-width: 760px) {
      .desktop-nav { display: none; }
      .icon-btn { display: inline-flex; }
      .hero { padding-top: 3.2rem; }
      .search-form { grid-template-columns: 1fr; }
      .btn-accent { width: 100%; min-height: 56px; }
      .stats-grid,
      .specialty-grid,
      .steps,
      .testimonials,
      .footer-grid { grid-template-columns: 1fr; }
      .section { padding: 3rem 0; }
    }
  </style>
</head>
<body>
  <header class="site-header" id="home">
    <div class="container header-row">
      <a href="index.html" class="brand" aria-label="MedBook home">
        <span class="brand-mark" aria-hidden="true"></span>
        MedBook
      </a>

      <nav class="desktop-nav" aria-label="Primary navigation">
        <a href="#specialties">Browse</a>
        <a href="#footer">Help</a>
        <a href="#">Log In</a>
        <a href="#" class="btn btn-primary">Sign Up</a>
      </nav>

      <button class="icon-btn" id="menuToggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobileDrawer">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M4 7h16M4 12h16M4 17h16" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
    </div>
  </header>

  <div class="drawer-overlay" id="drawerOverlay"></div>
  <aside class="mobile-drawer" id="mobileDrawer" aria-label="Mobile menu">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:.8rem;">
      <strong>Menu</strong>
      <button class="icon-btn" id="menuClose" aria-label="Close menu" style="display:inline-flex;">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
          <path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </button>
    </div>
    <nav class="drawer-links">
      <a href="#specialties">Browse</a>
      <a href="#">Log In</a>
      <a href="#">Sign Up</a>
    </nav>
  </aside>

  <main>
    <section class="hero">
      <div class="container hero-grid">
        <div>
          <h1>Find and book top doctors instantly.</h1>
          <p>An online healthcare appointment marketplace that connects patients with local doctors, dentists, and specialists for easy same-day booking.</p>
          <div class="trust-row" aria-label="Platform highlights">
            <span class="pill">Verified patient reviews</span>
            <span class="pill">Same-day availability</span>
            <span class="pill">Free for patients</span>
          </div>
        </div>

        <div class="hero-illustration" aria-hidden="true">
          <article class="doc-card">
            <div class="avatar">DR</div>
            <div>
              <p class="doc-name">Dr. Sofia Ramirez</p>
              <p class="doc-meta">Primary Care • 4.9 ★</p>
            </div>
            <span class="badge">Today 3:30 PM</span>
          </article>
          <article class="doc-card">
            <div class="avatar">DT</div>
            <div>
              <p class="doc-name">Dr. Ethan Kim</p>
              <p class="doc-meta">Dentist • 4.8 ★</p>
            </div>
            <span class="badge">Tomorrow 10:00 AM</span>
          </article>
          <article class="doc-card" style="margin-bottom:0;">
            <div class="avatar">DE</div>
            <div>
              <p class="doc-name">Dr. Maya Patel</p>
              <p class="doc-meta">Dermatologist • 4.9 ★</p>
            </div>
            <span class="badge">Today 5:00 PM</span>
          </article>
        </div>
      </div>
    </section>

    <section class="search-section" id="search">
      <div class="container">
        <div class="search-shell">
          <p class="search-title">Search by specialty, condition, or doctor name</p>
          <form class="search-form" id="searchForm" action="search-results.html" method="get">
            <div class="field-wrap">
              <input
                class="field"
                id="searchInput"
                name="query"
                type="text"
                autocomplete="off"
                placeholder="e.g. Dentist, Dr. Chen, back pain"
                aria-label="Search specialty, doctor, or condition"
              />
              <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
            </div>

            <input class="field" name="location" type="text" placeholder="City, ZIP, or neighborhood" aria-label="Location" />

            <button class="btn btn-accent" type="submit">Find a doctor</button>
          </form>
        </div>
      </div>
    </section>

    <section class="section section-alt" aria-label="Platform stats">
      <div class="container">
        <h2>Trusted by millions of patients</h2>
        <p class="lead">Quick, reliable access to care with transparent reviews and real-time availability.</p>
        <div class="stats-grid">
          <article class="stat"><strong>10M+</strong><span>Verified patient reviews</span></article>
          <article class="stat"><strong>120K+</strong><span>Providers across specialties</span></article>
          <article class="stat"><strong>Same-day</strong><span>Appointments available daily</span></article>
          <article class="stat"><strong>$0</strong><span>Always free to patients</span></article>
        </div>
      </div>
    </section>

    <section class="section" id="specialties">
      <div class="container">
        <h2>Popular specialties</h2>
        <p class="lead">Browse top categories and quickly jump to the right care.</p>
        <div class="specialty-grid" id="specialtyCards">
          <a class="specialty-card" href="search-results.html?specialty=Primary%20Care"><span class="icon">🩺</span>Primary Care</a>
          <a class="specialty-card" href="search-results.html?specialty=Dentist"><span class="icon">🦷</span>Dentist</a>
          <a class="specialty-card" href="search-results.html?specialty=Dermatologist"><span class="icon">✨</span>Dermatologist</a>
          <a class="specialty-card" href="search-results.html?specialty=Psychiatrist"><span class="icon">🧠</span>Psychiatrist</a>
          <a class="specialty-card" href="search-results.html?specialty=Eye%20Doctor"><span class="icon">👁️</span>Eye Doctor</a>
          <a class="specialty-card" href="search-results.html?specialty=Orthopedic%20Surgeon"><span class="icon">🦴</span>Orthopedic Surgeon</a>
        </div>
      </div>
    </section>

    <section class="section section-alt" id="how-it-works">
      <div class="container">
        <h2>How it works</h2>
        <p class="lead">Book care in minutes with a simple three-step flow.</p>
        <div class="steps">
          <article class="step">
            <div class="step-index">1</div>
            <h3>Search for a provider</h3>
            <p>Find doctors by specialty or condition and compare options instantly.</p>
          </article>
          <article class="step">
            <div class="step-index">2</div>
            <h3>Choose your time</h3>
            <p>See real-time availability and pick an appointment that fits your schedule.</p>
          </article>
          <article class="step">
            <div class="step-index">3</div>
            <h3>Book instantly</h3>
            <p>Reserve your visit online with immediate confirmation and reminders.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="testimonials">
      <div class="container">
        <h2>Patients love MedBook</h2>
        <p class="lead">Real stories from people who found the right care quickly.</p>
        <div class="testimonials">
          <article class="quote">
            <p>“I found a great dermatologist with evening availability during my lunch break. MedBook made it incredibly easy.”</p>
            <strong>Priya M., New York, NY</strong>
          </article>
          <article class="quote">
            <p>“As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes.”</p>
            <strong>James T., Chicago, IL</strong>
          </article>
          <article class="quote">
            <p>“I was dreading finding a new dentist, but the verified reviews gave me confidence. My appointment was exactly what I needed.”</p>
            <strong>Laura K., Austin, TX</strong>
          </article>
        </div>
      </div>
    </section>

    <section class="section section-alt" id="app">
      <div class="container">
        <div class="app-promo">
          <div>
            <h2>Your health, in your pocket</h2>
            <p class="lead" style="margin-bottom: .8rem;">Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go. Available on iOS and Android.</p>
            <div class="store-row">
              <a href="#" class="store-btn"> Download on the App Store</a>
              <a href="#" class="store-btn">▶ Get it on Google Play</a>
            </div>
          </div>
          <ul class="app-features" aria-label="App features">
            <li>Book and manage appointments anywhere</li>
            <li>Get real-time appointment reminders</li>
            <li>Access your visit history and provider details</li>
            <li>Read and leave verified reviews</li>
          </ul>
        </div>
      </div>
