  <script>
    const suggestionsData = [
      'Primary Care', 'Dentist', 'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon',
      'Dr. Chen', 'Dr. Patel', 'Dr. Garcia', 'Back pain', 'Anxiety', 'Skin rash', 'Annual physical'
    ];

    const searchInput = document.getElementById('searchInput');
    const suggestionsBox = document.getElementById('suggestions');
    let activeIndex = -1;
    let currentItems = [];

    function renderSuggestions(query) {
      const trimmed = query.trim().toLowerCase();
      if (!trimmed) {
        suggestionsBox.style.display = 'none';
        suggestionsBox.innerHTML = '';
        currentItems = [];
        return;
      }

      const matches = suggestionsData
        .filter(item => item.toLowerCase().includes(trimmed))
        .slice(0, 7);

      if (!matches.length) {
        suggestionsBox.style.display = 'none';
        suggestionsBox.innerHTML = '';
        currentItems = [];
        return;
      }

      suggestionsBox.innerHTML = matches.map((item, idx) => `
        <button type="button" class="suggestion ${idx === activeIndex ? 'active' : ''}" data-value="${item.replace(/"/g, '&quot;')}">
          <span aria-hidden="true">🔎</span>
          <span>${item}</span>
        </button>
      `).join('');

      suggestionsBox.style.display = 'block';
      currentItems = matches;

      suggestionsBox.querySelectorAll('.suggestion').forEach(btn => {
        btn.addEventListener('click', () => {
          searchInput.value = btn.dataset.value;
          suggestionsBox.style.display = 'none';
          searchInput.focus();
        });
      });
    }

    searchInput.addEventListener('input', (e) => {
      activeIndex = -1;
      renderSuggestions(e.target.value);
    });

    searchInput.addEventListener('keydown', (e) => {
      if (suggestionsBox.style.display !== 'block') return;

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        activeIndex = (activeIndex + 1) % currentItems.length;
        renderSuggestions(searchInput.value);
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        activeIndex = (activeIndex - 1 + currentItems.length) % currentItems.length;
        renderSuggestions(searchInput.value);
      } else if (e.key === 'Enter' && activeIndex >= 0) {
        e.preventDefault();
        searchInput.value = currentItems[activeIndex];
        suggestionsBox.style.display = 'none';
      } else if (e.key === 'Escape') {
        suggestionsBox.style.display = 'none';
      }
    });

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.field-wrap')) {
        suggestionsBox.style.display = 'none';
      }
    });

    const searchForm = document.getElementById('searchForm');
    searchForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const query = searchForm.query.value.trim();
      const location = searchForm.location.value.trim();
      const params = new URLSearchParams();
      if (query) params.set('query', query);
      if (location) params.set('location', location);
      window.location.href = `search-results.html?${params.toString()}`;
    });

    const menuToggle = document.getElementById('menuToggle');
    const menuClose = document.getElementById('menuClose');
    const drawer = document.getElementById('mobileDrawer');
    const overlay = document.getElementById('drawerOverlay');

    function setDrawer(open) {
      drawer.classList.toggle('open', open);
      overlay.classList.toggle('open', open);
      menuToggle.setAttribute('aria-expanded', String(open));
      document.body.style.overflow = open ? 'hidden' : '';
    }

    menuToggle.addEventListener('click', () => setDrawer(true));
    menuClose.addEventListener('click', () => setDrawer(false));
    overlay.addEventListener('click', () => setDrawer(false));

    drawer.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => setDrawer(false));
    });
  </script>
